      entry.valid = 0;

prediction_sum = 0;
for bank in 0..7:
  max_usefulness = -1;
  best_digest = 0;
  for reg in bank_registers[bank]:
    if logical_register_table[reg].valid:
      usefulness = sum(UT[bank][i][hash(PC)][reg] for i in 0..2);
      if usefulness > max_usefulness:
        max_usefulness = usefulness;
        best_digest = logical_register_table[reg].payload;
  if max_usefulness >= 0:
    prediction_sum += sum(WT[bank][i][hash(PC, best_digest)] for i in 0..2);
return prediction_sum;

